def pair_sums_to(nums, target):
    # Direct implementation of the spec.
    seen = set()
    pairs = set()
    for x in nums:
        complement = target - x
        if complement in seen:
            pairs.add(tuple(sorted((x, complement))))
        seen.add(x)
    return list(pairs)
