def fits_in_time(tasks, budget):
    # Try every combination; keep the best non-exceeding sum.
    from itertools import combinations
    best = ()
    best_sum = -1
    for r in range(len(tasks) + 1):
        for combo in combinations(tasks, r):
            s = sum(combo)
            if s <= budget and s > best_sum:
                best = combo
                best_sum = s
    return list(best)
```

