# Problem: max profit one buy + one sell, sell after buy.
# Track min-so-far and max-profit (= current_price - min_so_far) in one pass.
def best_time_to_buy(prices):
    if not prices:
        return 0
    min_price = prices[0]
    best = 0
    for p in prices[1:]:
        if p < min_price:
            min_price = p  # new buying low
        elif p - min_price > best:
            best = p - min_price  # better profit selling today
    return best
```

