# Problem: integer sqrt — largest k with k*k <= x.
# Binary search on k in [0, x]. Avoid floating-point sqrt to keep exactness.
def sqrt_int(x):
    if x < 2:
        return x
    lo, hi = 1, x // 2
    while lo <= hi:
        mid = (lo + hi) // 2
        if mid * mid == x:
            return mid  # exact
        elif mid * mid < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return hi  # largest k with k*k <= x
```

